create temporary table b2b_fixture_keys(k text primary key,v uuid);
grant select on b2b_fixture_keys to authenticated;
do $$
declare owner_id uuid:=gen_random_uuid();finance_id uuid:=gen_random_uuid();coordinator_id uuid:=gen_random_uuid();outsider_id uuid:=gen_random_uuid();admin_id uuid:=gen_random_uuid();unverified_id uuid:=gen_random_uuid();
 company_a uuid:=gen_random_uuid();company_b uuid:=gen_random_uuid();trip_id uuid:=gen_random_uuid();attempt_id uuid:=gen_random_uuid();request_id uuid;factor_id uuid:=gen_random_uuid();
 plan_id text;payload jsonb;failure text;workspace jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
 (owner_id,owner_id::text||'@example.invalid',now(),'{}'),(finance_id,finance_id::text||'@example.invalid',now(),'{}'),(coordinator_id,coordinator_id::text||'@example.invalid',now(),'{}'),(outsider_id,outsider_id::text||'@example.invalid',now(),'{}'),(admin_id,admin_id::text||'@example.invalid',now(),'{}'),(unverified_id,unverified_id::text||'@example.invalid',null,'{}');
 insert into public.admin_memberships(user_id) values(admin_id);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);
 failure:=null;begin perform public.b2b_apply('Self signup','','');exception when others then failure:=sqlerrm;end;if failure is distinct from 'admin_only' then raise exception 'public_application_allowed';end if;
 failure:=null;begin perform public.b2b_admin_company_create(owner_id,company_a,'Fake company',owner_id::text||'@example.invalid');exception when others then failure:=sqlerrm;end;if failure is distinct from 'admin_required' then raise exception 'ordinary_user_can_provision';end if;
 failure:=null;begin perform public.b2b_admin_company_create(admin_id,gen_random_uuid(),'Unverified',unverified_id::text||'@example.invalid');exception when others then failure:=sqlerrm;end;if failure is distinct from 'verified_account_required' then raise exception 'unverified_owner';end if;
 perform public.b2b_admin_action(admin_id,'create_company',jsonb_build_object('id',company_a,'name','Synthetic company A','email',owner_id::text||'@example.invalid'));
 perform public.b2b_admin_action(admin_id,'create_company',jsonb_build_object('id',company_a,'name','Synthetic company A','email',owner_id::text||'@example.invalid'));
 if(select count(*) from public.b2b_organizations where id=company_a)<>1 then raise exception 'duplicate_company';end if;
 perform public.b2b_admin_company_create(admin_id,company_b,'Synthetic company B',outsider_id::text||'@example.invalid');
 perform public.b2b_admin_member_add(admin_id,company_a,coordinator_id::text||'@example.invalid','coordinator');
 perform public.b2b_admin_member_add(admin_id,company_a,finance_id::text||'@example.invalid','finance');
 perform public.b2b_admin_member_add(admin_id,company_a,finance_id::text||'@example.invalid','finance');
 if(select count(*) from public.b2b_memberships where company_id=company_a)<>3 then raise exception 'duplicate_member';end if;
 if public.b2b_role(company_a)<>'owner' or public.b2b_role(company_b) is not null then raise exception 'company_isolation';end if;
 failure:=null;begin perform public.b2b_invite(company_a,'another@example.invalid','finance');exception when others then failure:=sqlerrm;end;if failure is distinct from 'admin_only' then raise exception 'owner_invitation_allowed';end if;
 failure:=null;begin perform public.b2b_accept_invitation(gen_random_uuid());exception when others then failure:=sqlerrm;end;if failure is distinct from 'admin_only' then raise exception 'legacy_acceptance_allowed';end if;
 failure:=null;begin perform public.b2b_admin_action(admin_id,'approve_application',jsonb_build_object('id',gen_random_uuid()));exception when others then failure:=sqlerrm;end;if failure is distinct from 'admin_only' then raise exception 'legacy_application_approval_allowed';end if;
 insert into b2b_fixture_keys values('coordinator',coordinator_id),('company_b',company_b),('trip',trip_id);
 payload:=jsonb_build_object('name','Japan group','destination','japan','departure','2026-12-20','returning','2026-12-26','travelers',30,'mode','package');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider_id,'role','authenticated')::text,true);perform public.b2b_create_trip(company_b,gen_random_uuid(),payload);
 failure:=null;begin perform public.b2b_workspace(company_a);exception when others then failure:=sqlerrm;end;if failure is distinct from 'company_required' then raise exception 'cross_company_read';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',finance_id,'role','authenticated','user_metadata',jsonb_build_object('role','owner'))::text,true);
 failure:=null;begin perform public.b2b_create_trip(company_a,trip_id,payload);exception when others then failure:=sqlerrm;end;if failure is distinct from 'role_required' then raise exception 'finance_can_create';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coordinator_id,'role','authenticated')::text,true);
 perform public.b2b_create_trip(company_a,trip_id,payload);perform public.b2b_create_trip(company_a,trip_id,payload);
 select p->>'id' into plan_id from jsonb_array_elements(public.b2b_catalog(company_a,'japan')) p where(p->>'days')::integer>=7 limit 1;
 if plan_id is null then raise exception 'test_catalog_empty';end if;
 failure:=null;begin perform public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,30,null);exception when others then failure:=sqlerrm;end;if failure is distinct from 'conflict' then raise exception 'null_version_bypass';end if;
 failure:=null;begin perform public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,29,1);exception when others then failure:=sqlerrm;end;if failure is distinct from 'invalid_quantity' then raise exception 'partial_package';end if;
 request_id:=public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,30,1);
 if request_id is distinct from public.b2b_submit_request(company_a,trip_id,attempt_id,plan_id,30,1) then raise exception 'duplicate_request';end if;
 perform public.b2b_admin_action(admin_id,'review_request',jsonb_build_object('id',request_id,'version',1,'decision','approved','note','Commercial review only'));
 workspace:=public.b2b_workspace(company_a);
 if workspace->'trips'->0->'request'->>'status'<>'approved' or jsonb_array_length(workspace->'members')<>0 then raise exception 'workspace_projection';end if;
 perform public.b2b_admin_action(admin_id,'company_status',jsonb_build_object('id',company_a,'status','suspended','note','Synthetic suspension'));
 failure:=null;begin perform public.b2b_workspace(company_a);exception when others then failure:=sqlerrm;end;if failure is distinct from 'company_required' then raise exception 'suspended_access';end if;
 perform public.b2b_admin_action(admin_id,'company_status',jsonb_build_object('id',company_a,'status','active','note','Synthetic restore'));
 insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values(factor_id,owner_id,'totp','verified','synthetic-only',now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','aal','aal1')::text,true);
 failure:=null;begin perform public.b2b_workspace(company_a);exception when others then failure:=sqlerrm;end;if failure is distinct from 'mfa_required' then raise exception 'mfa_bypass';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','aal','aal2')::text,true);perform public.b2b_workspace(company_a);delete from auth.mfa_factors where id=factor_id;
end;$$;
set local role authenticated;
do $$declare failure text;n integer;
begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',(select v from b2b_fixture_keys where k='coordinator'),'role','authenticated')::text,true);
 select count(*) into n from public.b2b_trips;if n<>1 then raise exception 'RLS_trip_visibility';end if;
 if has_function_privilege('authenticated','public.b2b_apply(text,text,text)','execute') or has_function_privilege('authenticated','public.b2b_invite(uuid,text,text)','execute') or has_function_privilege('authenticated','public.b2b_accept_invitation(uuid)','execute') or has_function_privilege('authenticated','public.b2b_admin_company_create(uuid,uuid,text,text)','execute') or has_function_privilege('authenticated','public.b2b_admin_legacy_action(uuid,text,jsonb)','execute') then raise exception 'public_creation_privilege';end if;
 failure:=null;begin insert into public.b2b_memberships(company_id,user_id,role) values((select v from b2b_fixture_keys where k='company_b'),auth.uid(),'owner');exception when insufficient_privilege then failure:='denied';end;if failure is distinct from 'denied' then raise exception 'direct_membership_mutation';end if;
end;$$;
reset role;
